/**
 * Theme Studio's phone previews: a sketch of each app screen with the same art and colours the app
 * uses (art in public/admin/theme, generated by the iOS repo's scripts/christmas_art/make_svgs.py;
 * colours from the iOS BrandColors / ChristmasDecor). Keep it in step with the app.
 */
export const ART = '/admin/theme';
export type PreviewScreen = 'home' | 'library' | 'search' | 'player';

const img = (name: string, cls: string) => `<img class="ts-art ${cls}" src="${ART}/${name}.svg" alt="" aria-hidden="true">`;
const flake = (cls: string) =>
  `<svg class="ts-art ts-flake ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2v20M3.3 7l17.4 10M3.3 17 20.7 7M12 2l-2 2m2-2 2 2m-2 18-2-2m2 2 2-2" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>`;
const cap = `<svg class="ts-art ts-cap" viewBox="0 0 60 12" preserveAspectRatio="none" aria-hidden="true"><path d="M0 0H60V5.5Q56 4 54 6C53 11 49 11 48 6Q41 4 35 6C34 10 30 10 29 6Q20 4 13 6C12 11 8 11 7 6Q3 4 0 5.5Z" fill="#fff"/></svg>`;
/** Faint six-armed flakes drifting slowly behind the content, like the app (few, slow, subtle). */
const snowfall = () =>
  `<div class="ts-snow" aria-hidden="true">${Array.from({ length: 7 }, (_, i) => `<i style="left:${(i * 41 + 7) % 96}%;animation-delay:-${(i * 6.3) % 40}s;animation-duration:${34 + (i % 4) * 5}s;--s:${0.7 + (i % 3) * 0.2}"></i>`).join('')}</div>`;
const header = (title: string, sub: string, bell = true) =>
  `<div class="ts-head">${img('xmas-pine-branch', 'ts-branch')}<div><b>${title}</b><span>${sub}</span></div>${bell ? '<span class="ts-bell"></span>' : ''}</div>`;

export function themePhone({ christmas, dark, screen }: { christmas: boolean; dark: boolean; screen: PreviewScreen }): string {
  const x = christmas ? ' xmas' : '';
  const mode = dark ? ' dark' : ' light';
  if (screen === 'player') {
    // holly hangs from the back button and the buttons at the right end of the top bar: the sheet
    // and the keyboard fill the rest of the screen, so that's where the app puts it
    return `<div class="ts-phone ts-landscape${mode}${x}"><div class="ts-screen ts-player">
      <div class="ts-col"><div class="ts-toolbar"><span class="ts-btn">‹${img('xmas-holly-corner', 'ts-holly-l')}</span><b class="ts-prompt">Play F3 · A4</b><span class="ts-btn ts-btn-wide"><span class="ts-pill"></span>${img('xmas-holly-corner', 'ts-holly-r')}</span></div>
      <div class="ts-sheet">${'<i></i>'.repeat(5)}<span class="ts-cursor"></span></div>
      <div class="ts-keys">${'<i></i>'.repeat(22)}</div></div>
    </div></div>`;
  }
  let body = '';
  if (screen === 'home') {
    body = `${header('Home', 'Welcome back')}
      <div class="ts-scan">${img('xmas-snow-scene', 'ts-scene')}${flake('f1')}${flake('f2')}${img('xmas-santa-hat', 'ts-hat')}
        <span class="ts-note">♪</span><b>Turn your sheet into music</b><span>Scan one page to hear it and start playing.</span></div>
      <div class="ts-cta">Scan to Play</div><div class="ts-link">Upload Music Sheet</div>
      <div class="ts-section"><b>Your Playlist</b><span>See more ›</span></div>
      <div class="ts-tiles"><i style="--a:#8a6fd1;--b:#5b4499">${cap}</i><i style="--a:#5c8f5a;--b:#2f5d3a">${cap}</i><i style="--a:#e0a25a;--b:#b5662b">${cap}</i></div>
      ${snowfall()}`;
  } else if (screen === 'library') {
    body = `${header('Library', 'Songs to learn and play')}
      <div class="ts-field">Search songs, composers…</div><div class="ts-chips"><i>Level</i><i>Skill</i></div>
      <div class="ts-section"><b>Songs</b></div>
      ${['Scarborough Fair', 'Melody in C', 'London Bridge', 'Ode to Joy'].map((s) => `<div class="ts-row"><i></i><b>${s}</b></div>`).join('')}
      ${snowfall()}`;
  } else {
    body = `${header('Search', 'Uploads, songs, playlists and lessons', false)}${img('xmas-ornament', 'ts-ornament')}
      <div class="ts-section"><b>Browse</b></div>
      <div class="ts-list">${['Scan Sheet Music', 'Library', 'Playlists', 'Practice Lessons', 'Notifications', 'Settings'].map((s) => `<div><i></i>${s}</div>`).join('')}</div>
      ${img('xmas-snow-gift', 'ts-landscape-art')}<div class="ts-searchbar">Uploads, songs, playlists…</div>
      ${snowfall()}`;
  }
  return `<div class="ts-phone${mode}${x}"><div class="ts-screen">${body}</div></div>`;
}
